{"cmd":"python - <<'PY'
import pandas as pd, re
for p in ['P1_POWER','P2_CTRL','P3_RF']:
    df=pd.read_csv(f'/app/data/codebook_{p}.csv')
    tokens=set()
    for s in df['keywords_examples'].dropna():
        for t in re.split(r'[ ,/;]+', s):
            if re.search(r'[A-Z]{1,4}\d', t) or '_' in t:
                tokens.add(t)
    print(p, 'tokens', sorted(tokens))
